-- BookSource - datos iniciales, volcados de la base SQL Server en produccion
-- (373 libros, 58 categorias, 8 usuarios, ...). Los textos se leyeron como WIN1252,
-- que era la codificacion de las columnas varchar originales.
BEGIN;

-- Reajustar las secuencias tras cargar ids explicitos
SELECT setval(pg_get_serial_sequence('category','idcategory'), COALESCE(MAX(idcategory),1), MAX(idcategory) IS NOT NULL) FROM category;
SELECT setval(pg_get_serial_sequence('"user"','iduser'), COALESCE(MAX(iduser),1), MAX(iduser) IS NOT NULL) FROM "user";
SELECT setval(pg_get_serial_sequence('book','idbook'), COALESCE(MAX(idbook),1), MAX(idbook) IS NOT NULL) FROM book;
SELECT setval(pg_get_serial_sequence('listofbooks','idlistofbooks'), COALESCE(MAX(idlistofbooks),1), MAX(idlistofbooks) IS NOT NULL) FROM listofbooks;
SELECT setval(pg_get_serial_sequence('publication','idpublication'), COALESCE(MAX(idpublication),1), MAX(idpublication) IS NOT NULL) FROM publication;
SELECT setval(pg_get_serial_sequence('review','idreview'), COALESCE(MAX(idreview),1), MAX(idreview) IS NOT NULL) FROM review;
COMMIT;
